cat > src/quote.py <<'PYEOF'
"""Premium calculation for MHPCO policies."""

PROCESSING_FEE = 5

BASE_PREMIUMS = {"sword": 100}


def item_base_premium(item):
    """Return the price-list base premium in G for one insured item."""
    return BASE_PREMIUMS[item["type"]]


def policy_base_premium(items):
    """Return the base premium in G for the insured items, before modifiers."""
    return sum(item_base_premium(item) for item in items)


def quote_premium(items):
    """Return the total premium in G for the given list of insured items."""
    return policy_base_premium(items) + PROCESSING_FEE
PYEOF
